<?php
require_once dirname(__DIR__) . '/core/Controller.php'; require_once dirname(__DIR__) . '/models/Sale.php'; require_once dirname(__DIR__) . '/models/Client.php';
class SalesController extends Controller { private Sale $model; private Client $clients; public function __construct(){ $this->model=new Sale();$this->clients=new Client(); } public function index():void{$this->requireModuleAccess('sales', ['Administrator','Sales Officer']);$this->view('sales/index',['title'=>'Sales','sales'=>$this->model->all(),'clients'=>$this->clients->all()]);} public function create():void{$this->requireLogin();if($_SERVER['REQUEST_METHOD']==='POST'&&$this->validateCsrf()){ $saleId = (int)$this->model->create($_POST+['sales_person_id'=>$_SESSION['user']['id']??null]); if($saleId > 0){ notifyTeam(['Administrator','Sales Officer'], 'New sale created', 'A sales record was created and needs follow-up.'); } }$this->redirect('/index.php?controller=sales');} public function status():void{$this->requireLogin();if($_SERVER['REQUEST_METHOD']==='POST'&&$this->validateCsrf()){ $saleId=$this->sanitizeInt($_POST['id']??0); $status=$this->sanitize($_POST['status']??'draft'); $this->model->updateStatus($saleId,$status); if($saleId > 0){ notifyTeam(['Administrator','Sales Officer'], 'Sale status changed', 'Sale #' . $saleId . ' is now marked as ' . $status . '.'); } }$this->redirect('/index.php?controller=sales');} }
